#include "exercise.h"
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <math.h>
void hangman_init(hangman*g,const char*w){size_t n=strlen(w);g->word=(char*)malloc(n+1);strcpy(g->word,w);g->masked=(char*)malloc(n+1);memset(g->masked,'_',n);g->masked[n]=0;memset(g->guesses,0,sizeof g->guesses);g->remaining=9;g->status=HANGMAN_ONGOING;}bool hangman_guess(hangman*g,unsigned char c){if(g->status!=HANGMAN_ONGOING)return false;if(g->guesses[c]||!strchr(g->word,c))g->remaining--;g->guesses[c]=true;for(size_t i=0;g->word[i];i++)if(g->guesses[(unsigned char)g->word[i]])g->masked[i]=g->word[i];if(!strcmp(g->word,g->masked))g->status=HANGMAN_WIN;else if(g->remaining<0)g->status=HANGMAN_LOSE;return true;}void hangman_free(hangman*g){free(g->word);free(g->masked);}

