static bool positive(int x){return x>0;}
static bool bstring(const void*p){return (*(const char*const*)p)[0]==98;}
static void string_length(const void*p,void*out){*(size_t*)out=strlen(*(const char*const*)p);}
int main(void){
hangman g;hangman_init(&g,"aba");assert(hangman_guess(&g,'a')&&!strcmp(g.masked,"a_a")&&g.remaining==9);assert(hangman_guess(&g,'a')&&g.remaining==8);assert(hangman_guess(&g,'b')&&g.status==HANGMAN_WIN);assert(!hangman_guess(&g,'x'));hangman_free(&g);hangman_init(&g,"a");for(int i=0;i<10;i++)assert(hangman_guess(&g,'x'));assert(g.status==HANGMAN_LOSE);hangman_free(&g);

return 0;}
